start();

function lastSeen(state){if(state.onlineUntil>Date.now())return 'online';return state.lastSeen?'visto por último em '+new Date(state.lastSeen).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'Visto por último ainda não disponível';}
function paintReceipts(){for(const label of document.querySelectorAll('[data-status]')){const seq=Number(label.dataset.status),read=seq<=(directState.read||0),delivered=seq<=(directState.delivered||0);label.textContent=read||delivered?'✓✓':'✓';label.classList.toggle('read',read);label.setAttribute('aria-label',read?'Visualizada':delivered?'Entregue ao aparelho':'Enviada; aguardando entrega');}}
function heartbeat(online){if(!account||!me||(!me.isAdmin&&me.status!=='approved'))return;const stamp=Date.now();if(online&&stamp-presenceAt<20000)return;presenceAt=online?stamp:0;fetch(API+'/v1/presence',{method:'POST',headers:{Authorization:'Bearer '+account.token,'Content-Type':'application/json'},body:JSON.stringify({online}),keepalive:!online}).catch(()=>{});}
async function confirmVisible(id=room){if(room!==id||roomInfo?.kind!=='direct')return;const old=receipts.get(id)||{delivered:0,read:0};let delivered=old.delivered,read=old.read;const visible=!document.hidden&&document.hasFocus()&&!modal.open&&!appLocked,header=document.querySelector('header')?.getBoundingClientRect().bottom||0,bottom=innerHeight-(document.querySelector('.composer-wrap')?.offsetHeight||document.querySelector('.composer')?.offsetHeight||0);for(const m of messages.values())if(m.author!==account.id){delivered=Math.max(delivered,m.seq);if(visible&&!appLocked&&privacyPrefs.readReceipts){const node=document.querySelector('.msg[data-seq="'+m.seq+'"]'),rect=node?.getBoundingClientRect();if(rect&&rect.top<bottom-20&&rect.bottom>header+20)read=Math.max(read,m.seq);}}if(delivered<=old.delivered&&read<=old.read)return;try{await api('/v1/rooms/'+id+'/receipts','POST',{delivered,read});receipts.set(id,{delivered,read});}catch{}}
let scrollReceipt;document.addEventListener('scroll',()=>{clearTimeout(scrollReceipt);scrollReceipt=setTimeout(()=>confirmVisible(),180);},{passive:true});window.addEventListener('focus',()=>confirmVisible());modal.addEventListener('close',()=>confirmVisible());
async function cropPhoto(file){if(!file)return null;if(file.size>25*1024*1024)throw Error('Escolha uma foto de até 25 MB.');const url=URL.createObjectURL(file),image=new Image();image.src=url;try{await image.decode();}catch{URL.revokeObjectURL(url);throw Error('Não foi possível abrir esta foto.');}return new Promise(resolve=>{let x=0,y=0,zoom=1,turn=0,flip=false,drag=null,finished=false;modal.innerHTML=`<h2>Ajustar foto de perfil</h2><p class="quiet">Arraste para enquadrar. Ajuste o zoom ou gire a foto.</p><canvas id="profile-crop" width="600" height="600" aria-label="Arraste para ajustar o corte da foto"></canvas><label>Zoom<input id="crop-zoom" aria-label="Zoom da foto" type="range" min="1" max="3" step=".01" value="1"></label><div class="row"><button id="crop-left" type="button">Girar ↶</button><button id="crop-right" type="button">Girar ↷</button><button id="crop-flip" type="button">Espelhar</button></div><p><button id="crop-save" class="primary full" type="button">Usar foto</button></p><button data-action="close" class="full">Cancelar</button>`;const canvas=modal.querySelector('canvas'),ctx=canvas.getContext('2d'),scale=()=>600/Math.min(image.naturalWidth,image.naturalHeight)*zoom;
function draw(guide=true,target=ctx,size=600){const factor=size/600,w=(turn%2?image.naturalHeight:image.naturalWidth)*scale(),h=(turn%2?image.naturalWidth:image.naturalHeight)*scale();x=Math.max(-(w-600)/2,Math.min((w-600)/2,x));y=Math.max(-(h-600)/2,Math.min((h-600)/2,y));target.save();target.clearRect(0,0,size,size);target.translate(size/2+x*factor,size/2+y*factor);target.scale(scale()*factor,scale()*factor);target.rotate(turn*Math.PI/2);target.scale(flip?-1:1,1);target.drawImage(image,-image.naturalWidth/2,-image.naturalHeight/2);target.restore();if(guide){target.strokeStyle='#ffedf5aa';target.lineWidth=2;for(const n of [200,400]){target.beginPath();target.moveTo(n,0);target.lineTo(n,600);target.moveTo(0,n);target.lineTo(600,n);target.stroke();}}}
canvas.onpointerdown=ev=>{canvas.setPointerCapture(ev.pointerId);drag={x:ev.clientX,y:ev.clientY};};canvas.onpointermove=ev=>{if(!drag)return;const factor=600/canvas.getBoundingClientRect().width;x+=(ev.clientX-drag.x)*factor;y+=(ev.clientY-drag.y)*factor;drag={x:ev.clientX,y:ev.clientY};draw();};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;modal.querySelector('#crop-zoom').oninput=ev=>{zoom=Number(ev.target.value);draw();};modal.querySelector('#crop-left').onclick=()=>{turn=(turn+3)%4;x=y=0;draw();};modal.querySelector('#crop-right').onclick=()=>{turn=(turn+1)%4;x=y=0;draw();};modal.querySelector('#crop-flip').onclick=()=>{flip=!flip;draw();};modal.querySelector('#crop-save').onclick=()=>{const out=document.createElement('canvas');out.width=out.height=400;draw(false,out.getContext('2d'),400);out.toBlob(async blob=>{if(!blob)return;const bytes=new Uint8Array(await blob.arrayBuffer());finished=true;modal.close();resolve(bytes);},'image/jpeg',.85);};modal.addEventListener('close',()=>{URL.revokeObjectURL(url);if(!finished)resolve(null);},{once:true});if(!modal.open)modal.showModal();draw();});}

function messagePreview(text){if(text.startsWith('ZL1:'))try{return JSON.parse(text.slice(4)).type==='image'?'📷 Foto':'🎤 Áudio';}catch{}return [...text].slice(0,140).join('');}
function chatMetadata(text){const extra={};if(replyTarget)extra.reply={...replyTarget};const mentions=[];for(const [userId,alias] of taggedPeople){const token='@'+alias;let at=text.indexOf(token);while(at>=0){const next=text[at+token.length];if(!next||!/[\p{L}\p{N}_]/u.test(next)){mentions.push({userId,alias});break;}at=text.indexOf(token,at+1);}}if(mentions.length)extra.mentions=mentions;return extra;}
function quoteHtml(reply){if(!reply||typeof reply!=='object')return '';return `<button class="quoted" data-action="quoted-original" data-id="${e(reply.id)}" data-seq="${Number(reply.seq)||0}"><strong>↪ ${e(reply.alias||'Mensagem')}</strong><br>${e(messagePreview(String(reply.preview||'')))}</button>`;}
function mentionHtml(text,tags){if(!Array.isArray(tags))return e(text);const spans=[];for(const tag of tags.slice(0,20)){if(!/^[a-f0-9-]{36}$/.test(tag.userId))continue;const token='@'+String(tag.alias||'');if(token==='@')continue;let at=text.indexOf(token);while(at>=0){if(!spans.some(s=>at<s.end&&at+token.length>s.start))spans.push({start:at,end:at+token.length,user:tag.userId});at=text.indexOf(token,at+token.length);}}spans.sort((a,b)=>a.start-b.start);let result='',pos=0;for(const span of spans){result+=e(text.slice(pos,span.start))+`<button class="mention" data-action="person" data-user="${e(span.user)}">${e(text.slice(span.start,span.end))}</button>`;pos=span.end;}return result+e(text.slice(pos));}
function renderReply(){const bar=document.querySelector('#reply-bar');if(!bar)return;bar.hidden=!replyTarget;bar.innerHTML=replyTarget?`<div><strong>Respondendo a ${e(replyTarget.alias)}</strong><br><span>${e(replyTarget.preview)}</span></div><button data-action="cancel-reply" aria-label="Cancelar resposta">×</button>`:'';}
async function setReply(seq){const m=messages.get(seq);if(!m||!room)return;const text=await C.decryptMessage(room,m,account.keys[room]);replyTarget={id:m.id,seq:m.seq,author:m.author,alias:m.alias,preview:messagePreview(text)};if(modal.open)modal.close();renderReply();document.querySelector('#send input').focus();}
async function mentionPicker(){if(roomInfo?.kind==='direct')return;const id=room,data=await api('/v1/rooms/'+id+'/mentionable');if(room!==id)return;mentionPeople=data.people;show('Mencionar participante',`<input id="mention-search" placeholder="Buscar participante" aria-label="Buscar participante"><div id="mention-results"></div>${data.limited?'<p class="quiet">Só aparecem pessoas que já escreveram no grupo.</p>':''}`);const search=modal.querySelector('#mention-search'),list=modal.querySelector('#mention-results');const draw=()=>{list.innerHTML=mentionPeople.filter(p=>p.alias.toLocaleLowerCase('pt-BR').includes(search.value.toLocaleLowerCase('pt-BR'))).map(p=>`<button class="full" data-action="pick-mention" data-user="${e(p.id)}">@${e(p.alias)}</button>`).join('')||'<p>Nenhum participante encontrado.</p>';};search.oninput=draw;draw();}
function pickMention(user){const p=mentionPeople.find(p=>p.id===user),input=document.querySelector('#send input');if(!p||!input)return;if(taggedPeople.size>=20&&!taggedPeople.has(user))throw Error('Use até 20 menções por mensagem.');const pos=input.selectionStart??input.value.length,start=pos>0&&input.value[pos-1]==='@'?pos-1:pos,token='@'+p.alias+' ';input.value=input.value.slice(0,start)+token+input.value.slice(pos);input.setSelectionRange(start+token.length,start+token.length);taggedPeople.set(user,p.alias);modal.close();input.focus();}
document.addEventListener('input',ev=>{if(ev.target.matches('#send input')&&ev.target.value.endsWith('@')&&roomInfo?.kind!=='direct')task(mentionPicker);});
async function originalMessage(id,seq){const node=document.querySelector('.msg[data-seq="'+seq+'"]');if(node&&messages.get(seq)?.id===id){node.scrollIntoView({block:'center',behavior:'smooth'});node.classList.add('highlight');setTimeout(()=>node.classList.remove('highlight'),1800);return;}const data=await api('/v1/rooms/'+room+'/message-context?messageId='+encodeURIComponent(id)),text=await C.decryptMessage(room,data.message,account.keys[room]);show(data.message.alias,`<p>${e(messagePreview(text))}</p>`);}
function muteMenu(){show('Notificações da conversa',`<p>Você continuará recebendo as mensagens ao abrir a conversa.</p><div class="stack">${[[480,'Silenciar por 8 horas'],[10080,'Silenciar por 1 semana'],[-1,'Silenciar sempre'],[0,'Ativar notificações']].map(([n,label])=>`<button data-action="set-mute" data-minutes="${n}">${label}</button>`).join('')}</div>`);}
async function setMute(minutes){const id=room,data=await api('/v1/rooms/'+id+'/notifications','POST',{minutes});if(room===id)roomInfo.muteUntil=data.muteUntil;if(minutes!==0&&sw?.getNotifications){for(const notice of await sw.getNotifications())if(notice.tag==='zap:message:'+id||notice.tag==='zap:mention:'+id)notice.close();}modal.close();toast(minutes===0?'Notificações ativadas.':'Notificações silenciadas.');}
function deleteConversation(){if(roomInfo?.kind!=='direct')return;show('Apagar conversa privada?',`<p>Apaga o histórico somente para você. A outra pessoa manterá as mensagens. Novas mensagens farão a conversa reaparecer.</p><button class="danger full" data-action="confirm-delete">Apagar para mim</button>`);}
async function confirmDelete(){const id=room;await api('/v1/rooms/'+id+'/delete-conversation','POST',{confirm:true});modal.close();messages.clear();receipts.delete(id);for(const [key,pending] of mediaCache)if(key.startsWith(account.id+':'+id+':')){mediaCache.delete(key);pending.then(url=>{URL.revokeObjectURL(url);mediaUrls.delete(url);}).catch(()=>{});}sw?.active?.postMessage({type:'forget-room',room:id});await home();toast('Conversa apagada para você.');}
function bindReplyGestures(){let drag,lastSwipe=0,lastSeq=0;document.addEventListener('pointerdown',ev=>{const msg=ev.target.closest('.msg');if(!msg||ev.target.closest('audio'))return;drag={seq:Number(msg.dataset.seq),x:ev.clientX,y:ev.clientY,dx:0,bubble:msg.querySelector('.bubble'),active:false};if(!ev.target.closest('button'))pressTimer=setTimeout(()=>{drag=null;messageOptions(Number(msg.dataset.seq));},500);});document.addEventListener('pointermove',ev=>{if(!drag)return;const dx=ev.clientX-drag.x,dy=ev.clientY-drag.y;if(Math.abs(dx)>8||Math.abs(dy)>8)clearTimeout(pressTimer);if(drag.active||(dx>14&&Math.abs(dx)>Math.abs(dy)*1.5)){drag.active=true;drag.dx=dx;drag.bubble.style.transform='translateX('+Math.max(0,Math.min(80,dx))+'px)';ev.preventDefault();}},{passive:false});for(const name of ['pointerup','pointercancel'])document.addEventListener(name,ev=>{clearTimeout(pressTimer);if(!drag)return;const d=drag;drag=null;d.bubble.style.transform='';if(name==='pointerup'&&d.active){lastSwipe=Date.now();lastSeq=d.seq;ev.preventDefault();if(d.dx>=48)task(()=>setReply(d.seq));}},{capture:true});document.addEventListener('click',ev=>{if(Date.now()-lastSwipe<350&&Number(ev.target.closest('.msg')?.dataset.seq)===lastSeq){ev.preventDefault();ev.stopImmediatePropagation();}},true);}
